calc.mjs.text:
// Certified payroll (Davis-Bacon / prevailing wage) arithmetic for one
// worker classification, one week. No network, no state.
//
// The one mistake this exists to catch: on a federal or federally-assisted
// construction contract, overtime is not simply 1.5x the base wage. Under
// the Contract Work Hours and Safety Standards Act (29 CFR 5.32) and the
// FLSA "regular rate" rule it borrows (29 CFR 778.7), any fringe benefit
// amount paid in cash — rather than contributed to a bona fide plan — counts
// toward the "regular rate" and must itself get the overtime premium.
// Fringe paid into a bona fide plan does not. Payroll software that applies
// time-and-a-half to the base rate only, and pays cash-in-lieu-of-fringe at
// straight time even during overtime hours, silently underpays every week it
// runs — a documented, recurring finding in DOL Davis-Bacon audits.
//
// This does not look up which wage determination applies, whether a
// contract is covered, or a worker's approved apprentice rate — those are
// facts from the contracting officer's wage determination and the
// contractor's own registered apprenticeship agreement, entered here, never
// inferred. It also does not know DOL rounding/reporting conventions used on
// the WH-347 form itself; treat every figure as the underlying math to check
// or carry into that form, not a filed report.

function number(value, name, { min = 0 } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  return result;
}

function optionalNumber(value, name, opts) {
  if (value === null || value === undefined || value === "") return null;
  return number(value, name, opts);
}

/**
 * @param {object} input
 * @param {number} input.requiredBaseRate     Basic hourly rate from the wage determination (or the worker's
 *   registered apprenticeship agreement if this row is an apprentice), $/hr.
 * @param {number} input.requiredFringeRate    Required fringe benefit rate from the same source, $/hr.
 * @param {number} input.actualBaseRate        Actual cash base hourly wage paid, $/hr.
 * @param {number} input.bonaFideFringePerHour Actual hourly-equivalent contribution paid to a bona fide
 *   fringe benefit plan (health, pension, etc.) — excluded from the overtime regular rate.
 * @param {number} input.cashFringePerHour     Fringe amount paid directly to the worker in cash instead of
 *   a plan — included in the overtime regular rate.
 * @param {number} input.straightHours         Hours worked at straight time this week.
 * @param {number} input.overtimeHours         Hours worked at time-and-a-half this week.
 * @param {number|null} input.approvedRatioApprentices Approved apprentice-to-journeyman ratio numerator (optional).
 * @param {number|null} input.approvedRatioJourneymen  Approved apprentice-to-journeyman ratio denominator (optional).
 * @param {number|null} input.journeymenOnSite  Journeymen in this classification on site this week (optional).
 * @param {number|null} input.apprenticesOnSite Apprentices in this classification on site this week (optional).
 * @param {number|null} input.fullJourneymanRate Full journeyman required total rate (base + fringe), used
 *   only to price the cost of any apprentices in excess of the approved ratio (optional).
 * @param {number|null} input.excessApprenticeHours Combined hours worked this week by apprentices in excess
 *   of the approved ratio, if any (optional).
 */
export function calculateCertifiedPayroll(input) {
  const requiredBaseRate = number(input.requiredBaseRate ?? 0, "Required base rate");
  const requiredFringeRate = number(input.requiredFringeRate ?? 0, "Required fringe rate");
  const actualBaseRate = number(input.actualBaseRate ?? 0, "Actual base rate");
  const bonaFideFringePerHour = number(input.bonaFideFringePerHour ?? 0, "Bona fide fringe per hour");
  const cashFringePerHour = number(input.cashFringePerHour ?? 0, "Cash fringe per hour");
  const straightHours = number(input.straightHours ?? 0, "Straight-time hours");
  const overtimeHours = number(input.overtimeHours ?? 0, "Overtime hours");

  const totalHours = straightHours + overtimeHours;

  const requiredTotalRate = requiredBaseRate + requiredFringeRate;
  const actualTotalRate = actualBaseRate + bonaFideFringePerHour + cashFringePerHour;
  const shortfallPerHour = Math.max(0, requiredTotalRate - actualTotalRate);

  // Correct: the overtime premium applies to the base cash rate plus any
  // cash-in-lieu-of-fringe, never to a bona fide plan contribution.
  const straightRatePerHour = actualBaseRate + cashFringePerHour;
  const otRatePerHour = straightRatePerHour * 1.5;
  const totalCashWagesPaid = straightHours * straightRatePerHour + overtimeHours * otRatePerHour;
  const totalBonaFideFringeDue = totalHours * bonaFideFringePerHour;
  const totalCompensationPaid = totalCashWagesPaid + totalBonaFideFringeDue;

  // The common payroll-system error: time-and-a-half on the base rate only,
  // with cash-in-lieu-of-fringe paid at straight time even on overtime
  // hours. Zero when there is no cash fringe to mishandle.
  const otRatePerHourIfFringeExcluded = actualBaseRate * 1.5 + cashFringePerHour;
  const totalCashWagesIfFringeExcludedFromOt =
    straightHours * straightRatePerHour + overtimeHours * otRatePerHourIfFringeExcluded;
  const otUnderpaymentIfCashFringeExcluded = totalCashWagesPaid - totalCashWagesIfFringeExcludedFromOt;

  const requiredGrossAtPrevailingWage =
    requiredBaseRate * straightHours + requiredBaseRate * 1.5 * overtimeHours + requiredFringeRate * totalHours;
  const underpaymentTotal = Math.max(0, requiredGrossAtPrevailingWage - totalCompensationPaid);

  // `shortfallPerHour === 0` is NOT enough to call a week compliant: it
  // compares a flat combined rate that treats fringe as fungible with base
  // pay, but overtime premium is only ever owed on base pay plus cash
  // fringe (never a bona fide plan contribution). A week can pay a
  // combined rate that matches the wage determination exactly and still
  // shortchange the worker once overtime hours are worked, if enough of
  // the required rate is delivered as bona fide fringe instead of base pay
  // -- fringe never earns the overtime premium, so shifting pay from base
  // into fringe silently erases part of the premium a compliant week owes.
  // `underpaymentTotal` already accounts for hours and the OT premium
  // correctly, so it is the only reliable compliance signal.
  const compliant = underpaymentTotal === 0;

  const approvedRatioApprentices = optionalNumber(input.approvedRatioApprentices, "Approved ratio (apprentices)", { min: 0 });
  const approvedRatioJourneymen = optionalNumber(input.approvedRatioJourneymen, "Approved ratio (journeymen)", { min: 0 });
  const journeymenOnSite = optionalNumber(input.journeymenOnSite, "Journeymen on site", { min: 0 });
  const apprenticesOnSite = optionalNumber(input.apprenticesOnSite, "Apprentices on site", { min: 0 });

  let ratio = null;
  if (
    approvedRatioApprentices !== null &&
    approvedRatioJourneymen !== null &&
    journeymenOnSite !== null &&
    apprenticesOnSite !== null
  ) {
    if (approvedRatioJourneymen === 0) throw new Error("Approved ratio (journeymen) must be greater than 0");
    const fullJourneymanRate = optionalNumber(input.fullJourneymanRate, "Full journeyman rate");
    const excessApprenticeHours = optionalNumber(input.excessApprenticeHours, "Excess apprentice hours");

    const allowed = Math.floor(journeymenOnSite * (approvedRatioApprentices / approvedRatioJourneymen));
    const excess = Math.max(0, apprenticesOnSite - allowed);
    const exceeded = excess > 0;
    const shortfallPerHour2 =
      fullJourneymanRate === null ? null : Math.max(0, fullJourneymanRate - actualTotalRate);
    const shortfallTotal =
      shortfallPerHour2 === null || excessApprenticeHours === null ? null : shortfallPerHour2 * excessApprenticeHours;

    ratio = { allowed, excess, exceeded, shortfallPerHour: shortfallPerHour2, shortfallTotal };
  }

  return {
    requiredTotalRate,
    actualTotalRate,
    shortfallPerHour,
    compliant,
    straightRatePerHour,
    otRatePerHour,
    totalCashWagesPaid,
    totalBonaFideFringeDue,
    totalCompensationPaid,
    otUnderpaymentIfCashFringeExcluded,
    requiredGrossAtPrevailingWage,
    underpaymentTotal,
    totalHours,
    ratio,
  };
}

share.mjs.text:
// Shareable week link.
//
// A link that reopens the calculator with the same figures already in it
// lets a payroll clerk hand a specific classification's numbers to the
// project's compliance officer, or to themselves next week, instead of
// retyping a dozen rates and hour counts from a wage determination.
//
// The transform is pure -- no DOM, no storage, no network -- and the page
// puts the payload in the URL fragment, which browsers never send to a
// server. Wage rates and hours stay on the two devices the link is pasted
// between, the same promise the rest of this calculator makes.
//
// The classification label is a free-text field used only for display and
// is deliberately not part of the link -- only the numbers that drive the
// arithmetic round-trip.

/** Mirrors the numeric FIELD_IDS in `index.html`. */
export const NUMBER_FIELD_IDS = Object.freeze([
  "requiredBaseRate", "requiredFringeRate", "actualBaseRate",
  "bonaFideFringePerHour", "cashFringePerHour", "straightHours", "overtimeHours",
  "approvedRatioApprentices", "approvedRatioJourneymen", "journeymenOnSite",
  "apprenticesOnSite", "fullJourneymanRate", "excessApprenticeHours",
]);

// `usageOptOut` is deliberately absent, same reasoning as every other share
// link in this fleet: it is the recipient's own privacy choice about their
// own browser, and a sender should not be able to switch counting back on --
// or off -- for someone else by handing them a link.

function usableNumber(value) {
  if (value === "" || value === null || value === undefined) return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) return null;
  return result;
}

/**
 * Encode the page's current numeric inputs as a URL fragment payload.
 *
 * Blank and unusable fields are omitted rather than sent as empty strings, so
 * the recipient's page keeps its own starting default for anything the
 * sender left alone instead of being handed a field it must treat as zero.
 */
export function encodeInputs(inputs) {
  const params = new URLSearchParams();
  for (const id of NUMBER_FIELD_IDS) {
    const value = usableNumber(inputs?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  return params.toString();
}

/**
 * Read a fragment (or query string) back into an input map.
 *
 * Anything unrecognised, negative, or non-numeric is dropped rather than
 * throwing: a truncated link pasted into a text message should open the page
 * on the fields that survived, not on an error.
 */
export function decodeInputs(source) {
  if (typeof source !== "string") return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ""));
  const inputs = {};
  for (const id of NUMBER_FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) inputs[id] = value;
  }
  return inputs;
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores wage
// rates, hours, classifications, or any other input, and it never leaves the
// device — payroll figures are exactly the sort of thing that must not be
// transmitted anywhere.
function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'week_calculated') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  const today = new Date().toISOString().slice(0, 10);
  const current = JSON.parse(storage.getItem('certified-payroll-usage') || '{}');
  current[event] = (current[event] || 0) + 1;
  current.last_day = today;
  storage.setItem('certified-payroll-usage', JSON.stringify(current));
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem('certified-payroll-usage-opt-out') === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem('certified-payroll-usage'); } catch { /* storage is optional */ }
    try { storage.setItem('certified-payroll-usage-opt-out', '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem('certified-payroll-usage-opt-out'); } catch { /* storage is optional */ }
  }
}

wh347.mjs.text:
// Weekly certified payroll report in the column layout of DOL form WH-347 (payroll sheet, front page): daily hours, total hours, rate, gross earned on
// this project, deductions and net pay, plus a per-worker prevailing-wage check. Pure functions, no network, no storage.
//
// Overtime follows calc.mjs: on a covered contract the time-and-a-half premium goes on base pay plus any cash fringe, never on a contribution to a bona
// fide plan. Hours over 40 in the workweek are overtime (CWHSSA, 29 CFR 5.32). Hours the worker put in elsewhere that week are entered as `otherHours`
// and are assumed to have come first, so overtime lands on this project's hours last. Change that and the split changes: check it against your own
// timekeeping. This is the arithmetic that fills the form, not the signed form or the Statement of Compliance on its back page.

import { calculateCertifiedPayroll } from "./calc.mjs";

export const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const round2 = (x) => Math.round((x + Number.EPSILON) * 100) / 100;
const round1 = (x) => Math.round((x + Number.EPSILON) * 10) / 10;

function nonNeg(v, label) {
  if (v === undefined || v === null || v === "") return 0;
  const n = Number(String(v).replace(/[$,\s]/g, ""));
  if (!Number.isFinite(n) || n < 0) throw new Error(`${label} must be a plain number that is not negative.`);
  return n;
}

export function buildWorker(w, index = 0) {
  const who = w.name && String(w.name).trim() ? String(w.name).trim() : `Worker ${index + 1}`;
  const label = (s) => `${who}: ${s}`;
  const flags = [];
  const id = String(w.idLast4 ?? "").trim();
  // WH-347 asks for the last four digits only. A longer entry is refused rather than echoed into a printout or a share link.
  if (id.length > 4) throw new Error(label("enter only the last four digits of the ID or SSN, never the whole number."));
  if (id && !/^\d{1,4}$/.test(id)) throw new Error(label("the ID field takes digits only, up to four."));
  if (id.length !== 4) flags.push("ID: the form wants the last four digits.");

  const days = DAYS.map((d, i) => nonNeg(Array.isArray(w.days) ? w.days[i] : w[d], label(`${d} hours`)));
  for (let i = 0; i < 7; i++) if (days[i] > 24) throw new Error(label(`${DAYS[i]} hours cannot be more than 24.`));
  const projectHours = days.reduce((a, b) => a + b, 0);
  const otherHours = nonNeg(w.otherHours, label("hours on other jobs"));
  const weekHours = projectHours + otherHours;
  const otAll = Math.max(0, weekHours - 40);
  const otHours = Math.min(projectHours, otAll);
  const straightHours = projectHours - otHours;

  const input = {
    requiredBaseRate: nonNeg(w.requiredBase, label("required base rate")),
    requiredFringeRate: nonNeg(w.requiredFringe, label("required fringe rate")),
    actualBaseRate: nonNeg(w.actualBase, label("base rate paid")),
    bonaFideFringePerHour: nonNeg(w.planFringe, label("fringe paid to a plan")),
    cashFringePerHour: nonNeg(w.cashFringe, label("fringe paid in cash")),
    straightHours,
    overtimeHours: otHours,
  };
  const c = calculateCertifiedPayroll(input);

  const fica = nonNeg(w.fica, label("FICA"));
  const withholding = nonNeg(w.withholding, label("withholding"));
  const otherDed = nonNeg(w.otherDeductions, label("other deductions"));
  const deductions = fica + withholding + otherDed;
  const gross = c.totalCashWagesPaid;
  const net = gross - deductions;

  if (!String(w.classification ?? "").trim()) flags.push("Classification is blank: the form needs the work classification from the wage determination.");
  if (projectHours === 0) flags.push("No hours on this project this week.");
  if (c.underpaymentTotal > 0.005) flags.push(`Underpaid against the wage determination by $${round2(c.underpaymentTotal).toFixed(2)} for the week.`);
  if (c.otUnderpaymentIfCashFringeExcluded > 0.005) flags.push(`Cash fringe counted in the overtime rate: $${round2(c.otUnderpaymentIfCashFringeExcluded).toFixed(2)} more than a system that pays overtime on base only.`);
  if (net < -0.005) flags.push("Deductions are more than gross pay.");
  if (input.bonaFideFringePerHour + input.cashFringePerHour < input.requiredFringeRate - 1e-9) flags.push("Fringe paid is below the required fringe rate; base pay must make up the difference, which the underpayment check above already tests.");

  return {
    name: who, idLast4: id, classification: String(w.classification ?? "").trim(), days, projectHours: round2(projectHours), otherHours: round2(otherHours),
    straightHours: round2(straightHours), overtimeHours: round2(otHours),
    ratePaid: round2(c.straightRatePerHour + input.bonaFideFringePerHour), otRate: round2(c.otRatePerHour),
    gross: round2(gross), planFringeDue: round2(c.totalBonaFideFringeDue),
    fica: round2(fica), withholding: round2(withholding), otherDeductions: round2(otherDed), deductions: round2(deductions), net: round2(net),
    requiredGross: round2(c.requiredGrossAtPrevailingWage), underpayment: round2(c.underpaymentTotal), compliant: c.compliant, flags,
  };
}

export function buildReport(input) {
  const h = input.header ?? {};
  const header = {
    contractor: String(h.contractor ?? "").trim(), project: String(h.project ?? "").trim(), contractNo: String(h.contractNo ?? "").trim(),
    payrollNo: String(h.payrollNo ?? "").trim(), weekEnding: String(h.weekEnding ?? "").trim(),
  };
  if (header.weekEnding && !/^\d{4}-\d{2}-\d{2}$/.test(header.weekEnding)) throw new Error("Week ending must be a date.");
  const list = Array.isArray(input.workers) ? input.workers : [];
  if (list.length === 0) throw new Error("Add at least one worker.");
  if (list.length > 60) throw new Error("This sheet takes up to 60 workers.");
  const workers = list.map((w, i) => buildWorker(w, i));
  const sum = (k) => round2(workers.reduce((a, w) => a + w[k], 0));
  const totals = {
    projectHours: round1(workers.reduce((a, w) => a + w.projectHours, 0)), overtimeHours: round1(workers.reduce((a, w) => a + w.overtimeHours, 0)),
    gross: sum("gross"), deductions: sum("deductions"), net: sum("net"), underpayment: sum("underpayment"),
  };
  const missing = [];
  if (!header.contractor) missing.push("contractor name");
  if (!header.project) missing.push("project and location");
  if (!header.weekEnding) missing.push("week ending date");
  if (!header.payrollNo) missing.push("payroll number");
  const flagged = workers.filter((w) => w.flags.length > 0).length;
  const advice = [];
  advice.push(`${workers.length} worker${workers.length === 1 ? "" : "s"}, ${totals.projectHours} hours on this project, $${totals.gross.toFixed(2)} gross, $${totals.net.toFixed(2)} net.`);
  if (totals.underpayment > 0.005) advice.push(`Underpayment against the wage determination totals $${totals.underpayment.toFixed(2)}. Pay it before you submit, and note it on the payroll.`);
  else advice.push("No underpayment against the rates you entered.");
  if (flagged) advice.push(`${flagged} worker row${flagged === 1 ? "" : "s"} carry a flag. Fix or understand each before you sign.`);
  if (missing.length) advice.push(`The form header still needs: ${missing.join(", ")}.`);
  return { header, workers, totals, advice, ready: totals.underpayment <= 0.005 && missing.length === 0 && flagged === 0 };
}

const csvCell = (s) => (/[",\n]/.test(String(s)) ? `"${String(s).replace(/"/g, '""')}"` : String(s));

export function toCsv(report) {
  const head = ["name", "id_last4", "classification", ...DAYS.map((d) => d.toLowerCase()), "project_hours", "overtime_hours", "rate_paid", "gross", "fica", "withholding", "other_deductions", "total_deductions", "net", "underpayment", "flags"];
  const rows = report.workers.map((w) => [w.name, w.idLast4, w.classification, ...w.days, w.projectHours, w.overtimeHours, w.ratePaid, w.gross, w.fica, w.withholding, w.otherDeductions, w.deductions, w.net, w.underpayment, w.flags.join(" | ")]);
  const t = report.totals;
  rows.push(["TOTAL", "", "", "", "", "", "", "", "", "", t.projectHours, t.overtimeHours, "", t.gross, "", "", "", t.deductions, t.net, t.underpayment, ""]);
  return [head, ...rows].map((r) => r.map(csvCell).join(",")).join("\n");
}

// Pasted from a spreadsheet: one worker per line, tab or comma separated.
// name, last4, classification, Mon..Sun hours (7), otherHours, requiredBase, requiredFringe, actualBase, planFringe, cashFringe, fica, withholding, otherDeductions
export const PASTE_COLUMNS = ["name", "idLast4", "classification", ...DAYS, "otherHours", "requiredBase", "requiredFringe", "actualBase", "planFringe", "cashFringe", "fica", "withholding", "otherDeductions"];

export function parsePaste(text) {
  const out = [];
  for (const line of String(text ?? "").split(/\r?\n/)) {
    if (!line.trim()) continue;
    const cells = line.includes("\t") ? line.split("\t") : line.split(",");
    const w = {};
    PASTE_COLUMNS.forEach((k, i) => { w[k] = (cells[i] ?? "").trim(); });
    if (/^name$/i.test(w.name)) continue;
    w.days = DAYS.map((d) => w[d]);
    out.push(w);
  }
  return out;
}

export function sampleReport() {
  return {
    header: { contractor: "Example Electric LLC (made up)", project: "Municipal Library Wiring, Springfield", contractNo: "DB-0000 (example)", payrollNo: "7", weekEnding: "2026-10-04" },
    workers: [
      { name: "A. Journeyman", idLast4: "1234", classification: "Electrician", days: [10, 10, 10, 10, 6, 0, 0], otherHours: 0, requiredBase: 38.5, requiredFringe: 14.2, actualBase: 38.5, planFringe: 9.2, cashFringe: 5, fica: 215.4, withholding: 330, otherDeductions: 0 },
      { name: "B. Apprentice", idLast4: "5678", classification: "Electrician apprentice (60%)", days: [8, 8, 8, 8, 8, 0, 0], otherHours: 0, requiredBase: 23.1, requiredFringe: 14.2, actualBase: 23.1, planFringe: 14.2, cashFringe: 0, fica: 106.4, withholding: 120, otherDeductions: 25 },
      { name: "C. Laborer", idLast4: "9012", classification: "Laborer", days: [8, 8, 8, 0, 0, 0, 0], otherHours: 20, requiredBase: 27, requiredFringe: 11, actualBase: 26, planFringe: 11, cashFringe: 0, fica: 70, withholding: 60, otherDeductions: 0 },
    ],
  };
}
